import logo from "./logo.svg";
import "./App.css";
import React from "react";
import { useState, useEffect } from "react";
//import { DndProvider } from "react-dnd";
//import { HTML5Backend } from "react-dnd-html5-backend";
import { Button, Skeleton } from "antd";
import { Modal } from "antd";
import apiClient from "./api/client";
import { apiEndpoints } from "./api/endpoints";
import { useDispatch, useSelector } from "react-redux";
import {
  setActiveClass,
  setCustomLayouts,
  setCustomLayoutsAvail,
  setLayoutIndex,
  setLayoutTitle,
  setLayoutKey,
} from "./store/builderSlice";
import { selectBuilderState } from "./store/selectors";
import {
  CheckOutlined,
  DeleteOutlined,
  EditOutlined,
  PlusOutlined,
  SyncOutlined,
} from "@ant-design/icons";
function App() {
  const dispatch = useDispatch();
  const {
    activeClass,
    customLayouts,
    customLayoutsAvail,
    layoutIndex,
  } = useSelector(selectBuilderState);
  const [addValue, setAddValue] = useState("");
  //const [exData, setExData] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [deleteIndex, setDeleteIndex] = useState('')
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const postId = urlParams.get('post-id');
    if (postId != undefined && postId != null) {
      dispatch(setActiveClass("caf-pop-active"));
      dispatch(setLayoutIndex(postId));
      getData()
    }
  }, []);
  const getData = async () => {
    const { data } = await apiClient.get(apiEndpoints.layouts);
    if (data) {
      if (data.status == "success") {
        dispatch(setCustomLayouts(data.layouts));
        dispatch(setCustomLayoutsAvail(data.layouts_saved));
      }
    }
  };
  useEffect(() => {
    getData();
  }, [activeClass]);
  const AvailableLayout = () => {
    // reserved for future layout status action
  };
  const ActivePopUP = (event) => {
    let index = event.target.closest("button").getAttribute("data_index");
    dispatch(
      setLayoutIndex(event.target.closest("button").getAttribute("data_index"))
    );
    dispatch(
      setLayoutTitle(event.target.closest("button").getAttribute("data_title"))
    );
    dispatch(setLayoutKey(event.target.closest("button").getAttribute("data_key")));
    dispatch(setActiveClass("caf-pop-active"));
    const url = new URL(window.location.href);
    url.searchParams.set('post-id', index);
    window.history.pushState({}, '', url);
  };
  const deleteMe = (event) => {
    setIsModalOpen(true);
    setDeleteIndex(event.currentTarget);
  };

  const saveValue = (event) => {
    setAddValue(event.target.value);
  };
  const addLayout = (event) => {
    if (addValue.length > 0) {
      apiClient
        .get(apiEndpoints.addOptions(addValue))
        .then((response) => {
          if (response.data) {
            if (response.data.status == "success") {
              dispatch(setCustomLayouts(response.data.layouts));
              setAddValue("");
              const lastSection = Object.keys(response.data.layouts);
              const lastSectionLen = lastSection.length;
              const lastSectionLabel = Object.values(response.data.layouts)?.slice(-1)[0]?.label;
              const lastSectionKey = Object.values(response.data.layouts)?.slice(-1)[0]?.key;
              dispatch(setLayoutIndex(parseInt(lastSection[lastSectionLen - 1])));
              dispatch(setLayoutTitle(lastSectionLabel));
              dispatch(setLayoutKey(lastSectionKey));
              dispatch(setActiveClass("caf-pop-active"));
              const indexid = parseInt(lastSection[lastSectionLen - 1])
              const url = new URL(window.location.href);
              url.searchParams.set('post-id', indexid);
              window.history.pushState({}, '', url);
            }
          }
        });
    }
  };

  const handleEnterKeyPress = (e) => {
    if (e.key === 'Enter') {
      addLayout();
    }
  };
  const handleCancel = () => {
    setIsModalOpen(false);
  }
  const handleOk = () => {
    const index = parseInt(deleteIndex.getAttribute("data_index"));
    apiClient
      .get(apiEndpoints.deleteOptions(index))
      .then((response) => {
        if (response.data) {
          if (response.data.status == "success") {
            dispatch(setCustomLayouts(response.data.layouts));
          }
        }
      });
    setIsModalOpen(false)
  }
  return (
    <>
      {customLayouts ? <>
        <div className="caf-wrap">
          <Modal
            open={isModalOpen}
            onOk={handleOk}
            onCancel={handleCancel}
            className="caf-app-delete-layout-modal caf-builder-modal"
          >
            <p>Are you sure, want to delete this post layout </p>
          </Modal>
          <div className="caf-builder-main">
            <h1>Custom Post Layouts</h1>
          </div>
          <div className="caf-builder-layouts">

            {Object.keys(customLayouts).length > 0 ? (

              Object.keys(customLayouts).map((key, index) => {
                return (
                  <>
                    <div className="caf-builder-layout">
                      <div className="caf-builder-layout-serial">
                        {parseInt(index) + 1}
                      </div>
                      <div className="caf-builder-layout-title">
                        {customLayouts[key].label}
                      </div>
                      <div className="caf-builder-layout-buttons">
                        <Button
                          title="Delete"
                          type="default"
                          shape="default"
                          size="medium"
                          className="caf-layout-delete-btn"
                          data_index={key}
                          onClick={deleteMe}
                          icon={
                            <DeleteOutlined />
                          }
                        />

                        <Button
                          title="Build it"
                          type="default"
                          shape="default"
                          size="medium"
                          className="caf-layout-build-btn"
                          data_index={key}
                          data_title={customLayouts[key]['label']}
                          data_key={customLayouts[key]['key']}
                          onClick={ActivePopUP}
                          icon={
                            <EditOutlined
                              data_index={key}
                              onClick={ActivePopUP}
                            />
                          }
                        />

                        <Button
                          title={customLayoutsAvail?.[key] ? "Saved" : "Not Saved"}
                          type="default"
                          shape="default"
                          size="medium"
                          className="caf-layout-available-btn"
                          data_index={key}
                          icon={
                            customLayoutsAvail?.[key] ? (
                              <CheckOutlined onClick={AvailableLayout} />
                            ) : (
                              <SyncOutlined onClick={AvailableLayout} />
                            )
                          }
                        />
                      </div>
                    </div>
                  </>
                );
              })
            ) : (
              !customLayouts ? <Skeleton active /> : ''
            )}
            <div className="caf-builder-add-btn">
              <input
                type="text"
                className="caf-builder-input"
                placeholder="Add New Layout"
                value={addValue}
                onChange={saveValue}
                onKeyDown={handleEnterKeyPress}
              />
              <Button
                title="Add"
                type="default"
                shape="default"
                size="medium"
                className="caf-layout-add-btn"
                icon={<PlusOutlined onClick={addLayout} />}
              />
            </div>
          </div>
          {/* <Tooltip title="prompt text" placement="right">
    <span>Tooltip will show on mouse enter.</span>
  </Tooltip> */}
        </div>
        <>{activeClass == "caf-pop-active" && (
          <div id="root" className="popup-content">
            <div className="caf-root-class">
              <Header />
              <div className="builder-content-container">
                <MainSidebar />
              </div>
            </div>
          </div>
        )}
        </>
      </> : <><Skeleton active />
        <Skeleton active />
      </>}
    </>

  );
}

export default App;
