const DraggableCheckbox = ({ item, id, groupKey, settings, validateTerm, updatedTaxonomy, isDragDisabled, itemLayoutClasses, textCount,textCountVeritcal, iconText,iconTextVeritcal, isSelected, onToggle }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id: id, disabled: isDragDisabled });

  const valid = validateTerm(groupKey, item.key, updatedTaxonomy);
  if (!valid) return null;

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const showCheckboxEnabled = settings?.show_checkbox === "true";
  const showIconEnabled = settings?.show_icon === "true";
  const showCountEnabled = settings?.show_count === "true";

  return (
    <li
      className={`caf-terms-list-item ${itemLayoutClasses} ${
        isSelected ? "caf-selected" : ""
      } ${showCheckboxEnabled ? "caf-show-checkbox" : "caf-hidden-checkbox"} ${
        showIconEnabled ? "caf-show-icon" : "caf-hidden-icon"
      } ${showCountEnabled ? "caf-show-count" : "caf-hidden-count"}`}
      ref={setNodeRef}
      style={style}
      onClick={(e) => {
        e.stopPropagation();
        onToggle(item.key);
      }}
    >
      <input
        type="checkbox"
        className={`caf-taxo-input`}
        value={item.key}
        name="caf-taxo-input"
        style={{ display: 'none' }}   // 👈 hidden checkbox
        checked={isSelected}
        readOnly
        data-predefined={isSelected}                        // 👈 prevent React warnings
      />
      {settings?.show_checkbox === 'true' && (
        <span className="caf-checkbox-box"></span>

      )}
      <div className={`manage-ic-lbl caf-layout-${iconText} ${iconTextVeritcal}`}>

        {item.icons?.icon && item.icons?.type === 'icon' && settings?.show_icon === 'true' && (
          <i className={`fa-solid ${item.icons.icon} filter-before-icon`} />
        )}
        {item.icons?.icon && item.icons?.type === 'svg' && settings?.show_icon === 'true' && (
          <InlineSVG
            src={item.icons?.icon?.url}
            className="caf-inline-svg-icon"
          />
        )}
        <div className={`manage-text-lbl caf-layout-${textCount} ${textCountVeritcal}`}>
          <span className="trm-name">{parse(`${item?.value}`)}</span>

          {settings?.show_count === 'true' && (
            <span className="count-span">
              {/* Prefix */}
              {settings?.count_separator === 'brackets' && '('}
              {settings?.count_separator === 'hyphen' && '- '}
              {settings?.count_separator === 'custom' && settings?.count_prefix}

              {/* Count */}
              {item?.count}

              {/* Suffix */}
              {settings?.count_separator === 'brackets' && ')'}
              {settings?.count_separator === 'custom' && settings?.count_suffix}
            </span>
          )}

        </div>
        {item.icons?.icon && item.icons?.position === "after" && settings?.show_icon === 'true' && (
          <i className={`fa-solid ${item.icons.icon} filter-after-icon`} />
        )}
      </div>
      {/* </label> */}
    </li>
  );
};

