const InlineSVG = memo(({ src, className }) => {
  const [svg, setSvg] = useState(null);

  useEffect(() => {
    if (!src) return;

    // ✅ CASE 1: Cache exists → hydrate state
    if (svgCache.has(src)) {
      const cachedSvg = svgCache.get(src);

      setSvg((prev) => (prev === cachedSvg ? prev : cachedSvg));
      return;
    }

    // ✅ CASE 2: Not cached → fetch
    fetch(src)
      .then((res) => res.text())
      .then((text) => {
        svgCache.set(src, text);
        setSvg(text);
      })
      .catch(() => {});
  }, [src]);

  if (!svg) return null;

  return (
    <span
      className={className}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
});

const isPredefinedTermMatched = (predefinedTerms = [], itemId) => {
  const currentTerm = predefinedTerms[0];

  if (!currentTerm?.includes("___")) {
    return false;
  }

  return currentTerm.includes(`___${itemId}`);
};

