import { builderLayoutData } from "../BuilderLayoutData";
import newRowData from "../FilterComponents/components/newElementData/newRow";
import { getFilterModuleForLibrary } from "./filterLibraryModules";

const deepClone = (value) => JSON.parse(JSON.stringify(value));

export const FILTER_LIBRARY_TABS = [
  { key: "full_filter", label: "Full Filter" },
  { key: "checkbox_filter", label: "Checkbox" },
  { key: "dropdown_filter", label: "Dropdown" },
  { key: "range_slider", label: "Range Slider" },
  { key: "search", label: "Search" },
  { key: "reset", label: "Reset" },
];

const MODULE_TAB_KEYS = FILTER_LIBRARY_TABS.filter(
  (tab) => tab.key !== "full_filter"
).map((tab) => tab.key);

const createBaseLayout = ({ name, postType }) => {
  const layout = deepClone(builderLayoutData);
  layout.common_data.layout_name = name;
  layout.common_data.post_type = postType;
  layout.post_layout_data.extra_data = {
    ...(layout.post_layout_data.extra_data || {}),
    post_type: postType,
  };
  layout.filter_layout_data.extra_data = {
    ...(layout.filter_layout_data.extra_data || {}),
    post_type: postType,
  };
  return layout;
};

const buildFilterLayoutWithModule = (moduleKey, { name, postType }) => {
  const module = getFilterModuleForLibrary(moduleKey);
  if (!module) {
    return null;
  }

  const layout = createBaseLayout({ name, postType });
  const row = deepClone(newRowData);
  row.data[0].data = [module];
  layout.filter_layout_data.initial_data = [row];

  return {
    common_data: deepClone(layout.common_data),
    filter_layout_data: deepClone(layout.filter_layout_data),
  };
};

const buildLayoutSettingsPayload = (layout, postType) => ({
  common_data: {
    layout_name: layout.common_data.layout_name,
    post_type: postType,
    preview_template_data: deepClone(layout.common_data.preview_template_data),
  },
});

const fullTemplate = createBaseLayout({
  name: "Default Full Filter Layout",
  postType: "post",
});

const filterTemplateBase = createBaseLayout({
  name: "Default Filter Layout",
  postType: "post",
});

const postTemplateBase = createBaseLayout({
  name: "Default Single Post Item",
  postType: "post",
});

const settingsTemplate = createBaseLayout({
  name: "Default Layout Settings",
  postType: "post",
});

const moduleTemplateMeta = {
  checkbox_filter: {
    title: "Checkbox Filter",
    description: "Single checkbox filter module from the default builder layout.",
    postType: "post",
    file: "filter/checkbox/checkbox-filter.json",
  },
  dropdown_filter: {
    title: "Dropdown Filter",
    description: "Single dropdown filter module from the default builder layout.",
    postType: "post",
    file: "filter/dropdown/dropdown-filter.json",
  },
  range_slider: {
    title: "Range Slider",
    description: "Single range slider module from the default builder layout.",
    postType: "post",
    file: "filter/range-slider/range-slider.json",
  },
  search: {
    title: "Search",
    description: "Single search module from the default builder layout.",
    postType: "post",
    file: "filter/search/search.json",
  },
  reset: {
    title: "Reset",
    description: "Single reset module from the default builder layout.",
    postType: "post",
    file: "filter/reset/reset.json",
  },
};

const buildModuleTemplates = () =>
  MODULE_TAB_KEYS.map((moduleKey) => {
    const meta = moduleTemplateMeta[moduleKey] || {
      title: moduleKey,
      description: "Filter layout with a single module.",
      postType: "post",
      file: `filter/${moduleKey}/${moduleKey}.json`,
    };
    const payload = buildFilterLayoutWithModule(moduleKey, {
      name: `Library ${meta.title}`,
      postType: meta.postType,
    });

    if (!payload) {
      return null;
    }

    return {
      id: `library_filter_${moduleKey}`,
      title: meta.title,
      section: "filter",
      filterLibraryTab: moduleKey,
      scope: "filter_layout",
      description: meta.description,
      file: meta.file,
      payload,
    };
  }).filter(Boolean);

export const buildImportLibraryTemplates = () => [
  {
    id: "library_full_filter_layout",
    title: "Default Full Filter Layout",
    section: "full_filter_layout",
    scope: "full_layout",
    description:
      "Complete filter, post, and preview settings from the default builder layout.",
    file: "full-filter-layout/default-full-layout.json",
    payload: deepClone(fullTemplate),
  },
  {
    id: "library_filter_full",
    title: "Default Filter Layout",
    section: "filter",
    filterLibraryTab: "full_filter",
    scope: "filter_layout",
    description: "Full filter area from the default builder layout.",
    file: "filter/full-filter/default-filter-layout.json",
    payload: {
      common_data: deepClone(filterTemplateBase.common_data),
      filter_layout_data: deepClone(filterTemplateBase.filter_layout_data),
    },
  },
  ...buildModuleTemplates(),
  {
    id: "library_single_post_item",
    title: "Default Single Post Item",
    section: "single_post_item",
    scope: "post_layout",
    description: "Post card layout from the default builder layout.",
    file: "single-post-item/default-post-item.json",
    payload: {
      common_data: deepClone(postTemplateBase.common_data),
      post_layout_data: deepClone(postTemplateBase.post_layout_data),
    },
  },
  {
    id: "library_layout_settings",
    title: "Default Layout Settings",
    section: "layout_settings",
    scope: "layout_settings",
    description:
      "Preview container, misc items, and layout settings from the default builder layout.",
    file: "layout-settings/default-layout-settings.json",
    payload: buildLayoutSettingsPayload(settingsTemplate, "post"),
  },
];

export const getDummyLibraryTemplates = () => buildImportLibraryTemplates();
