import React, { useState, useEffect, memo, useRef } from "react";
import { generateFilterCSS } from "../../../utils/functions";
const svgCache = new Map();

const InlineSVG = memo(({ src, className }) => {
  const [svg, setSvg] = useState(null);

  useEffect(() => {
    if (!src) return;

    // ✅ CASE 1: Cache exists → hydrate state
    if (svgCache.has(src)) {
      const cachedSvg = svgCache.get(src);

      setSvg((prev) => (prev === cachedSvg ? prev : cachedSvg));
      return;
    }

    // ✅ CASE 2: Not cached → fetch
    fetch(src)
      .then((res) => res.text())
      .then((text) => {
        svgCache.set(src, text);
        setSvg(text);
      })
      .catch(() => {});
  }, [src]);

  if (!svg) return null;

  return (
    <span className={className} dangerouslySetInnerHTML={{ __html: svg }} />
  );
});
function ModuleReset({
  postData,
  settings,
  styleDefault,
  module,
  rowindex,
  columnindex,
  moduleindex,
  selectedDevice,
  setIndexes,
  indexes,
}) {
  let custom_class = "";
  if (settings?.custom_class) {
    custom_class = settings.custom_class;
  }

    const visibility = settings?.visibility || {};
  const hideClass =
  visibility?.[selectedDevice] === "true" ? "caf-hide-element" : "";

  return (
    <div
      onClick={() =>
        setIndexes &&
        setIndexes({
          type: "module",
          rowindex: rowindex,
          columnindex: columnindex,
          moduleindex: moduleindex,
          module: module,
        })
      }
      className={`caf-builder-module-main caf-module-${
        module.key
      } caf-module-${moduleindex} ${custom_class} caf-builder-filter ${
        indexes?.type === "module" &&
        indexes?.rowindex === rowindex &&
        indexes?.columnindex === columnindex &&
        indexes?.moduleindex === moduleindex
          ? "active"
          : ""
      } ${hideClass}`}
    >
      {(settings?.icons && settings?.icons?.visibility  &&
        settings?.icons?.type === "icon" &&
        settings?.icons?.icon !== "") ||
      (settings?.icons &&
        settings?.icons?.type === "svg" &&
        settings?.icons?.icon?.url &&
        settings?.icons?.icon.url.toLowerCase().endsWith(".svg")) ? (
        <>
          {settings?.icons &&
            settings?.icons?.type === "icon" &&
            settings?.icons?.icon !== "" && (
              <i className={settings?.icons?.icon}></i>
            )}
          {settings?.icons &&
            settings?.icons?.type === "svg" &&
            settings?.icons?.icon?.url &&
            settings?.icons?.icon.url.toLowerCase().endsWith(".svg") && (
              <InlineSVG
                src={settings?.icons?.icon?.url}
                className="caf-inline-svg-icon"
              />
            )}
          <div className="caf-builder-reset-label">{settings.reset_label}</div>
        </>
      ) : (
        <>{settings.reset_label}</>
      )}

      {/* {settings?.icons && settings?.icons?.icon != "" ? (
        <>
          <div className="caf-builder-custom-filed-label">
            {settings?.icons.position == "before-reset" && (
              <span
                className={`caf-builder-before-label reset-icon-common ${settings?.icons.icon}`}
              ></span>
            )}
            {settings.reset_label}
            {settings?.icons.position == "after-reset" && (
              <span
                className={`caf-builder-after-label reset-icon-common ${settings?.icons.icon}`}
              ></span>
            )}
          </div>
        </>
      ) : (
        <div className="caf-builder-custom-filed-label">
          {settings.reset_label}
        </div>
      )} */}

      <style>
        {`
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex}{
              ${generateFilterCSS(
                "container",
                "default",
                selectedDevice,
                styleDefault,
              )}
          }
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex}:hover{
            ${generateFilterCSS(
              "container",
              "hover",
              selectedDevice,
              styleDefault,
            )}
          }
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex} i ,
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex} svg {
              ${generateFilterCSS(
                "icon",
                "default",
                selectedDevice,
                styleDefault,
              )}
          }
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex} i:hover , 
          .caf-bl-filter .caf-row-${rowindex} .caf-column-${columnindex} .caf-module-${moduleindex} i:hover {
            ${generateFilterCSS(
              "icon",
              "hover",
              selectedDevice,
              styleDefault,
            )}
          }
        `}
      </style>
    </div>
  );
}

export default ModuleReset;
