import { Select, Switch, Input ,Segmented ,Skeleton, Tooltip} from "antd";
import React, { useEffect, useState, useRef } from "react";
import ContentIcons from "./ContentComponents/ContentIcons";
import apiClient from "../../../../../api/client";
import { apiEndpoints } from "../../../../../api/endpoints";
import {
  commitPostModuleSettingsPatch,
} from "./postLayoutSnapshot";
import { usePostTypeCustomFieldOptions } from "../../../../utils/usePostTypeCustomFieldOptions";
const CUSTOM_FIELD_META_TEXT_DEFAULTS = {
  prefix: "Prefix",
  suffix: "Suffix",
};
const getDefaultMetaText = (placement) =>
  CUSTOM_FIELD_META_TEXT_DEFAULTS[placement] || "Text";
const normalizeMetaText = (placement, value) => {
  const nextValue = typeof value === "string" ? value.trim() : "";
  return nextValue !== "" ? nextValue : getDefaultMetaText(placement);
};
function ModuleCustomFieldContent(props) {
  const builderPostData = props.postPreviewData || {};
  const { rowindex, columnindex, moduleindex } = props.indexes;
  const modSettings =
    props.data[rowindex]?.data[columnindex]?.data[moduleindex]?.settings || {};
  const { options: meta_object, loading: cfFieldListLoading } =
    usePostTypeCustomFieldOptions({
      includeValue: modSettings?.custom_field,
    });

  //console.log(props.indexes)

  const path_url = tc_caf_ajax.plugin_path;
  let icons_url = path_url + "admin/fa-icons/fontawesome-5.json";

  const [checkPrefix, setCheckPrefix] = useState(
    modSettings?.prefix?.is_enable === "false" ? false : true
  );
  const [checkSuffix, setCheckSuffix] = useState(
    modSettings?.suffix?.is_enable === "false" ? false : true
  );
  // const [labelInput, setLabelInput] = useState(item.label.value);
  const [iconsArray, setIconsArray] = useState("");
 
  const [cfLoading, setCfLoading] = useState(false);
  const [placementTab ,setPlacementTab] = useState("prefix")
  const [prefixMeta , setPrefixMeta] = useState(modSettings?.prefix?.meta_type ?? 'text')
  const [suffixMeta , setSuffixMeta] = useState(modSettings?.suffix?.meta_type ?? 'text')
  const [prefixMetaText , setPrefixMetaText] = useState(
    modSettings?.prefix?.is_enable === "true" &&
      (modSettings?.prefix?.meta_type ?? "text") === "text"
      ? normalizeMetaText("prefix", modSettings?.prefix?.meta_text)
      : modSettings?.prefix?.meta_text ?? ''
  )
  const [suffixMetaText , setSuffixMetaText] = useState(
    modSettings?.suffix?.is_enable === "true" &&
      (modSettings?.suffix?.meta_type ?? "text") === "text"
      ? normalizeMetaText("suffix", modSettings?.suffix?.meta_text)
      : modSettings?.suffix?.meta_text ?? ''
  )
  const isFirstRender = useRef(true);
  useEffect(() => {
    setCheckPrefix(modSettings?.prefix?.is_enable === "false" ? false : true);
    setCheckSuffix(modSettings?.suffix?.is_enable === "false" ? false : true);
    setPrefixMeta(modSettings?.prefix?.meta_type ?? "text");
    setSuffixMeta(modSettings?.suffix?.meta_type ?? "text");
    setPrefixMetaText(
      modSettings?.prefix?.is_enable === "true" &&
        (modSettings?.prefix?.meta_type ?? "text") === "text"
        ? normalizeMetaText("prefix", modSettings?.prefix?.meta_text)
        : modSettings?.prefix?.meta_text ?? ""
    );
    setSuffixMetaText(
      modSettings?.suffix?.is_enable === "true" &&
        (modSettings?.suffix?.meta_type ?? "text") === "text"
        ? normalizeMetaText("suffix", modSettings?.suffix?.meta_text)
        : modSettings?.suffix?.meta_text ?? ""
    );
  }, [props.data, rowindex, columnindex, moduleindex]);
  useEffect(() => {
    const prefixType = modSettings?.prefix?.meta_type ?? "text";
    const suffixType = modSettings?.suffix?.meta_type ?? "text";
    const shouldPatchPrefix =
      modSettings?.prefix?.is_enable === "true" &&
      prefixType === "text" &&
      normalizeMetaText("prefix", modSettings?.prefix?.meta_text) !==
        (modSettings?.prefix?.meta_text ?? "");
    const shouldPatchSuffix =
      modSettings?.suffix?.is_enable === "true" &&
      suffixType === "text" &&
      normalizeMetaText("suffix", modSettings?.suffix?.meta_text) !==
        (modSettings?.suffix?.meta_text ?? "");
    if (!shouldPatchPrefix && !shouldPatchSuffix) return;
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        if (shouldPatchPrefix) {
          s.prefix = {
            ...(s.prefix || {}),
            meta_text: normalizeMetaText("prefix", s?.prefix?.meta_text),
          };
        }
        if (shouldPatchSuffix) {
          s.suffix = {
            ...(s.suffix || {}),
            meta_text: normalizeMetaText("suffix", s?.suffix?.meta_text),
          };
        }
      },
    });
  }, [props.data, rowindex, columnindex, moduleindex]);
  useEffect(() => {
    if (modSettings?.custom_field !== "0") {
      fetchCfValue(builderPostData?.value, modSettings?.custom_field);
    }
  }, []);

    useEffect(() => {
    const fetchIcons = async () => {
      try {
        const response = await apiClient.get(icons_url);
        // console.log(response)
        if (response.data) {
          setIconsArray(response.data);
        }
      } catch (error) {
        console.error("Error ", error);
      }
    };

    fetchIcons();
  }, []);
// console.log(iconsArray)
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false; // next time effect will run
      return; // skip first run
    }
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.custom_field = "0";
      },
    });
  }, [builderPostData?.value]); // reset on post /post type change

  const fetchCfValue = async (postId, fieldName) => {
    setCfLoading(true);
    const postedData = {
      post_id: postId,
      field_name: fieldName,
    };

    const res = await apiClient.post(apiEndpoints.getCfFieldValue, postedData);
    const value = res?.data?.data?.value;
    setCfLoading(false);
    return value;
  };

  

  const handleChange = async (value) => {
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.custom_field = value;
      },
    });
    if(value !== "0"){
    await fetchCfValue(builderPostData?.value, value); 
    }
  };
  const handleChangePrefix = (checked) => {
    setCheckPrefix(checked);
    if (checked && prefixMeta === "text") {
      setPrefixMetaText(normalizeMetaText("prefix", modSettings?.prefix?.meta_text));
    }
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.prefix = {
          ...(s.prefix || {}),
          is_enable: checked ? "true" : "false",
          meta_text:
            checked && (s?.prefix?.meta_type ?? "text") === "text"
              ? normalizeMetaText("prefix", s?.prefix?.meta_text)
              : s?.prefix?.meta_text ?? "",
        };
      },
    });
  };
    const handleChangeSuffix = (checked) => {
    setCheckSuffix(checked);
    if (checked && suffixMeta === "text") {
      setSuffixMetaText(normalizeMetaText("suffix", modSettings?.suffix?.meta_text));
    }
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.suffix = {
          ...(s.suffix || {}),
          is_enable: checked ? "true" : "false",
          meta_text:
            checked && (s?.suffix?.meta_type ?? "text") === "text"
              ? normalizeMetaText("suffix", s?.suffix?.meta_text)
              : s?.suffix?.meta_text ?? "",
        };
      },
    });
  };
  // const handleLabel = (val) => {
  //   setLabelInput(val);
  //   item.label.value = val;
  //   items[rowindex].data[columnindex].data[moduleindex]["settings"] = item;
  //   props.onSettingChange(props.data);
  // };
  const onSettingChange = (data) => {
    props.onSettingChange(data);
  };

  const onhandlePlacement=(tab)=>{
    setPlacementTab(tab)
  }
  const handleMetaChange =(val,placement)=>{
    if(placement === "prefix"){
      setPrefixMeta(val)
    }
    if(placement === "suffix"){
      setSuffixMeta(val)
    }
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        const isEnabled = s?.[placement]?.is_enable === "true";
        const nextMeta = {
          ...(s[placement] || {}),
          meta_type: val,
        };
        if (isEnabled && val === "text") {
          nextMeta.meta_text = normalizeMetaText(placement, nextMeta.meta_text);
        }
        s[placement] = {
          ...nextMeta,
        };
      },
    });
  }
  const handleMetaText =(val,placement)=>{
    const isTextMode =
      placement === "prefix"
        ? prefixMeta === "text"
        : placement === "suffix"
          ? suffixMeta === "text"
          : false;
    const isEnabled =
      placement === "prefix"
        ? checkPrefix
        : placement === "suffix"
          ? checkSuffix
          : false;
    const nextVal =
      isTextMode && isEnabled ? normalizeMetaText(placement, val) : val;
    if(placement === "prefix"){
      setPrefixMetaText(nextVal)
    }
    if(placement === "suffix"){
      setSuffixMetaText(nextVal)
    }
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s[placement] = {
          ...(s[placement] || {}),
          meta_text: nextVal,
        };
      },
    });
  }
  const handleMetaTextBlur = (placement, value) => {
    const isTextMode =
      placement === "prefix"
        ? prefixMeta === "text"
        : placement === "suffix"
          ? suffixMeta === "text"
          : false;
    const isEnabled =
      placement === "prefix"
        ? checkPrefix
        : placement === "suffix"
          ? checkSuffix
          : false;
    if (!isTextMode || !isEnabled) return;
    const normalized = normalizeMetaText(placement, value);
    if (placement === "prefix") setPrefixMetaText(normalized);
    if (placement === "suffix") setSuffixMetaText(normalized);
    commitPostModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s[placement] = {
          ...(s[placement] || {}),
          meta_text: normalized,
        };
      },
    });
  };
  return (
    <>
      <label className="setting-label-main">Field Source</label>
      <div className="module-content-tab-row caf-design-two-half">
        <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Select custom field key.">
          <label>Select Field</label>
        </Tooltip>
        <Select
          defaultValue={modSettings?.custom_field}
          style={{
            width: "100%",
          }}
          value={modSettings?.custom_field}
          onChange={handleChange}
          options={meta_object}
          loading={cfLoading || cfFieldListLoading}
        />
      </div>
      <div className="setting-manage-f-label">
        <hr className="setting-hr-main"></hr>
        <label className="setting-label-main">Prefix <span className="setting-label-sub-text">(Before Value)</span></label>
        <div className="module-content-tab-row caf-design-two-half">
          <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Enable or disable prefix.">
            <label>Enable</label>
          </Tooltip>
          <Switch
            onChange={handleChangePrefix}
            checked={checkPrefix}
          />
        </div>
        {checkPrefix && (
          <>
          <div className="module-content-tab-row caf-design-two-half">
            <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Select prefix content type.">
              <label>Content Type</label>
            </Tooltip>
             <Segmented
              value={prefixMeta}
              // style={{ marginBottom: 20 }}
              onChange={(value) => handleMetaChange(value, 'prefix')}
              className={'hoverTabCaf'}
              options={[
                { label: 'Text', value: 'text', },
                { label: 'Icon', value: 'icon', },
              ]}
              />
          </div>
          {prefixMeta === "text" && 
          <div className="module-content-tab-row caf-design-two-half">
            <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Set prefix text value.">
              <label>Text</label>
            </Tooltip>
           <Input
            onChange={(e) => handleMetaText(e.target.value,'prefix')}
            value={prefixMetaText}
            onBlur={(e) => handleMetaTextBlur("prefix", e.target.value)}
            />
            </div>
          }
          {prefixMeta === "icon" && 
          <div className="module-content-tab-row">
            {iconsArray.length > 0 ? (
               <ContentIcons
                title="Icons"
                labelType={"label"}
                moduleIcon="prefix"
                data={props.data}
                indexes={props.indexes}
                iconsArray={iconsArray}
                onSettingChange={props.onSettingChange}
              ></ContentIcons>
            ) : (
              <Skeleton active></Skeleton>
            )}
          </div>
          }
          </>
        )}
      </div>
      <div className="setting-manage-f-label">
        <hr className="setting-hr-main"></hr>
        <label className="setting-label-main">Suffix <span className="setting-label-sub-text">(After Value)</span></label>
        <div className="module-content-tab-row caf-design-two-half">
          <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Enable or disable suffix.">
            <label>Enable</label>
          </Tooltip>
          <Switch
            onChange={handleChangeSuffix}
            checked={checkSuffix}
          />
        </div>
        {checkSuffix && (
          <>
        <div className="module-content-tab-row caf-design-two-half">
            <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Select suffix content type.">
              <label>Content Type</label>
            </Tooltip>
             <Segmented
              value={suffixMeta}
              // style={{ marginBottom: 20 }}
              onChange={(value) => handleMetaChange(value, 'suffix')}
              className={'hoverTabCaf'}
              options={[
                { label: 'Text', value: 'text', },
                { label: 'Icon', value: 'icon', },
              ]}
              />
          </div>
               {suffixMeta === "text" && 
            <div className="module-content-tab-row caf-design-two-half">
            <Tooltip classNames={{ root: "caf-builder-tooltip" }} placement="topLeft" title="Set suffix text value.">
              <label>Text</label>
            </Tooltip>
            <Input
            onChange={(e) => handleMetaText(e.target.value,'suffix')}
            value={suffixMetaText}
            onBlur={(e) => handleMetaTextBlur("suffix", e.target.value)}
            />
            </div>
          }
          {suffixMeta === "icon" && 
          <div className="module-content-tab-row">
            {iconsArray.length > 0 ? (
               <ContentIcons
                title="Icons"
                labelType={"label"}
                moduleIcon="suffix"
                data={props.data}
                indexes={props.indexes}
                iconsArray={iconsArray}
                onSettingChange={props.onSettingChange}
              ></ContentIcons>
            ) : (
              <Skeleton active></Skeleton>
            )}
          </div>
          }
          </>
        )}
      </div>
    </>
  );
}

export default ModuleCustomFieldContent;
