import React, { useState, useEffect } from "react";
import apiClient from "../../../../api/client";
import {getSiteBaseUrl} from "../../../../api/client";
import { apiEndpoints } from "../../../../api/endpoints";
import { Skeleton } from "antd";
import {
  resolvePostTypeFromBuilderData,
  resolvePreviewTemplateDataFromBuilderData
} from "../../../utils/builderDataAdapters";
import { canUseFeature } from "../../../../tier/capabilities";

function ElementorLoopTemplate(props) {
  if (!canUseFeature("elementor_loop")) {
    return null;
  }
  const previewTemplateData = resolvePreviewTemplateDataFromBuilderData(
    props.mainBuilderData
  );
  let postPreviewData = {
    ...previewTemplateData.post_preview_data,
  };
  let selectedDevice = props.deviceType
  const [elementorLoopId, setElementorLoopId] = useState(
    props?.mainBuilderData?.post_layout_data?.extra_data?.loop_template_id ?? ""
  );
  const [elementorStatus, setElementorStatus] = useState(false);
  const [elementorLoopTemplateData, setElementorLoopTemplateData] = useState(
    []
  );
  const builderResolvedPostType = resolvePostTypeFromBuilderData({...props?.mainBuilderData});
  const [loading, setLoading] = useState(true);
  const [html, setHtml] = useState("");
  const WP_BASE = getSiteBaseUrl(); 

  useEffect(() => {
    getElementorStatusLoopTemplateData();
  }, [elementorLoopId]);

const getElementorStatusLoopTemplateData = async () => {
  try {
    const response = await apiClient.get(
      apiEndpoints.getElementorStatusLoopTemplateData(elementorLoopId, builderResolvedPostType)
    );

    if (response.data.status == "success") {
      console.log(response.data);
      setElementorStatus(response.data.elementor_status);
      setElementorLoopTemplateData(response.data.elementor_loop_template_data);
      setHtml(response.data.html);
      loadGlobalCSS();
      loadCSS(response.data.css_url, `elementor-css-${elementorLoopId}`);
      setLoading(false);
    }
  } catch (error) {
    console.error(error);
  } finally {
  }
};

  // ✅ CSS loader
  const loadCSS = (url, id) => {
    if (!url) return;
    if (document.getElementById(id)) return;

    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  };

  const loadGlobalCSS = () => {
    // Elementor base
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor/assets/css/frontend.min.css`,
      "elementor-global"
    );
  
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor/assets/lib/eicons/css/elementor-icons.min.css`,
      "elementor-icons"
    );
  
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor/assets/css/widget-icon-list.min.css`,
      "icon-list"
    );
  
    // 🔥 ADD THESE (important widgets)
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor/assets/css/widget-image.min.css`,
      "elementor-image"
    );
  
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor/assets/css/widget-heading.min.css`,
      "elementor-heading"
    );
    loadCSS(
      `${WP_BASE}/wp-content/plugins/elementor-pro/assets/css/widget-loop-grid.min.css`,
      "elementor-heading-pro"
    );
  
  
    // 🔥 DIVI (IMPORTANT for colors + layout)
    loadCSS(`${WP_BASE}/wp-content/themes/Divi/style.css`, "divi-parent");
  
    // 🔥 Divi builder CSS (bahut important)
    loadCSS(
      `${WP_BASE}/wp-content/themes/Divi/includes/builder/styles/frontend-builder-plugin-style.min.css`,
      "divi-builder"
    );
  
    // Child theme
    loadCSS(
      `${WP_BASE}/wp-content/themes/divi-child/style.css`,
      "divi-child"
    );
  };
  return (

    <>
    {!loading && elementorStatus ? (
      <div
      className="caf-builder-preview-post-template caf-elementor-posts-loop elementor-loop-container elementor-grid"
      style={{
        gridTemplateColumns: `repeat(${postPreviewData.grid?.device_columns?.[selectedDevice]}, 1fr)`,
        columnGap:`${postPreviewData?.inner?.style?.[selectedDevice]?.default?.columnGap}`,
        rowGap:`${postPreviewData?.inner?.style?.[selectedDevice]?.default?.rowGap}`
       }}
      dangerouslySetInnerHTML={{ __html: html }}>
      </div>
    ) : (
        <Skeleton />
    )}
    </>
  );
}

export default ElementorLoopTemplate;
